/** Decodifica i byte originali della pagina 417 (browser e jsdom). */
export function saleConditionsPdfBytes(): Uint8Array {
  const binary = atob(SALE_CONDITIONS_PDF_BASE64);
  const bytes = new Uint8Array(binary.length);
  for (let i = 0; i < binary.length; i++) bytes[i] = binary.charCodeAt(i);
  return bytes;
}
